int nfc_target_deactivate(struct sk_buff *skb, struct genl_info *info)
{
	int dev_idx;
	int target_idx;
	struct nfc_dev *nfc_dev;
	int rc;

	dev_idx = nfc_get_dev_idx_from_attrs(info);
	target_idx = nfc_get_target_idx_from_attrs(info);

	if (dev_idx < 0 || target_idx < 0)
		return -EINVAL;

	nfc_dev = nfc_get_device_by_index(dev_idx);
	if (!nfc_dev)
		return -ENODEV;

	rc = nfc_dev->ops->target_deactivate(nfc_dev, target_idx);

	nfc_put_device(nfc_dev);
	return rc;
}

int nfc_deactivate_target(struct sk_buff *skb, struct genl_info *info)
{
	int did, tid;
	struct nfc_dev *dev;
	int rc;

	if (!info->attrs[NFC_ATTR_DEVICE_INDEX] ||
	    !info->attrs[NFC_ATTR_TARGET_INDEX])
		return -EINVAL;

	did = nla_get_u32(info->attrs[NFC_ATTR_DEVICE_INDEX]);
	tid = nla_get_u32(info->attrs[NFC_ATTR_TARGET_INDEX]);

	dev = nfc_get_device(did);
	if (!dev)
		return -ENODEV;

	rc = nfc_target_deactivate(dev, tid);
	nfc_put_device(dev);

	return rc;
}

